Q: Oracle APEX Interactive Grid – How to perform row-level validation with async server call before save? A: <p>In addition, giving you below solution. After your existing DML process, add another process:</p>
<pre><code>begin
   if has_overlap(:ITEM_D, :START_DATE, :END_DATE) then 
       raise_application_error(-20001, 'No overlapping date ranges allowed for an item (Item: ' || :ITEM_ID || ').');
   end if;
end;
</code></pre>
<p>On the process properties, 'Error' section, you can make this a user friendly message.
So like this, you first run all updates, inserts and deletes (but no commit), so you can apply your function and in case of an overlap, the raise_application_error will abort the transaction and report back to the client.</p>

Q: SwiftUI How to Set Specific Width Ratios for Child Elements in an HStack A: <p>Based on the answers that I have read in this question, here is my take.</p>
<p>I have added the ability to configure spacing between elements</p>
<p>here is the code</p>
<pre><code>import SwiftUI

// 1. THE KEY
struct LayoutWeight: LayoutValueKey {
    static let defaultValue: Int = 0 // Default 0 means &quot;use natural size&quot;
}

// 2. THE MODIFIER
extension View {
    func layoutWeight(_ value: Int) -&gt; some View {
        layoutValue(key: LayoutWeight.self, value: value)
    }
}

// 3. THE UPGRADED ENGINE (Handles Spacing + Weights)
struct WeightedHStack: Layout {
    var spacing: CGFloat? = nil

    typealias Cache = ViewInfo
    struct ViewInfo {
        let weights: [Int]
        let sumOfWeights: Int
        let idealMaxHeight: CGFloat
    }

    func makeCache(subviews: Subviews) -&gt; ViewInfo {
        var weights = [Int]()
        var idealMaxHeight = CGFloat.zero
        for subview in subviews {
            let idealViewSize = subview.sizeThatFits(.unspecified)
            idealMaxHeight = max(idealMaxHeight, idealViewSize.height)
            weights.append(subview[LayoutWeight.self])
        }
        return ViewInfo(weights: weights, sumOfWeights: weights.reduce(0, +), idealMaxHeight: idealMaxHeight)
    }

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ViewInfo) -&gt; CGSize {
        return CGSize(width: proposal.width ?? 10, height: cache.idealMaxHeight)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ViewInfo) {
        guard subviews.count &gt; 0 else { return }

        // 1. Calculate Total Spacing
        let space = spacing ?? 0
        let totalSpacing = space * CGFloat(subviews.count - 1)

        // 2. Calculate Unit Width (Total Width - Gaps) / Sum of Weights
        let availableWidth = bounds.width - totalSpacing
        let unitWidth = availableWidth / CGFloat(max(1, cache.sumOfWeights))

        var currentX = bounds.minX

        for (index, subview) in subviews.enumerated() {
            let weight = cache.weights[index]

            // Calculate width for this child
            let vWidth = CGFloat(weight) * unitWidth
            let vHeight = bounds.height

            // Place the view
            subview.place(
                at: CGPoint(x: currentX, y: bounds.midY),
                anchor: .leading,
                proposal: ProposedViewSize(width: vWidth, height: vHeight)
            )

            // Advance cursor: View Width + Gap
            currentX += vWidth + space
        }
    }
}
</code></pre>
